import * as T from './three.module.js';import {roadSurface,roadMarkings} from './road-layout.js?v=vehicles14';
export function buildRoads(scene){const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(roadSurface(),3));geo.computeVertexNormals();const surface=new T.Mesh(geo,new T.MeshStandardMaterial({color:'#555d5d',roughness:.97}));surface.name='Continuous county and regional asphalt';surface.receiveShadow=true;scene.add(surface);const lines=roadMarkings(),batch=new T.InstancedMesh(new T.BoxGeometry(1,1,1),new T.MeshStandardMaterial({color:'#eee7ca',roughness:.9}),lines.length),dummy=new T.Object3D();batch.name='County road batch';lines.forEach((r,i)=>{dummy.position.set(r.x,.278,r.z);dummy.scale.set(r.w,.012,r.d);dummy.updateMatrix();batch.setMatrixAt(i,dummy.matrix);});batch.computeBoundingSphere();scene.add(batch);return {surface,batch};}
